MATCH (v:PlantItem:CheckValve {unit_id: '47'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem {tag: 'P-2704'})-[:line_to*1..]->(v:Valve)
WHERE EXISTS { (v)-[:line_to*1..]->(:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: 'D-2701'})-[:is_drawn_on]->(sheet:Sheet)
RETURN item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (:PlantItem {tag: 'R-3301'})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (anchor:PlantItem {tag: 'V-2801'}), (v:Valve)-[:line_to]-(anchor), (loop:ProcessControlFunction)-[:send_signal_to*1..]->(act:PlantItem)-[:control]->(v)
RETURN DISTINCT loop.loop_tag AS tag
ORDER BY tag;

MATCH (e:Equipment)-[:measured_by]->(s:PlantItem)-[:send_signal_to*0..]->(head:ProcessInstrumentationFunction {loop_tag: 'PI-41020'})
RETURN DISTINCT e.tag AS tag
