MATCH (e:Equipment)-[:measured_by]->(s:PlantItem)
WHERE EXISTS {
  (s)-[:send_signal_to*0..]->(:ProcessInstrumentationFunction {loop_tag: 'TI-48075'})
}
RETURN DISTINCT e.tag AS tag
