MATCH (a:PlantItem {tag: 'EJ-4301A'}), (b:PlantItem {tag: 'E-4302'}), (v:PlantItem {tag: 'GTV-43015'})
RETURN a.tag AS source_tag, b.tag AS destination_tag,
       EXISTS {
         MATCH (a) ((x)-[:line_to]->(y) WHERE x <> v AND y <> v)+ (b)
       } AS reachable_without_valve

MATCH (a:PlantItem {tag: 'P-802'}), (b:PlantItem {tag: 'P-902'}), (blocked:PlantItem {tag: 'BFV-9003'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x)-[:line_to]->(y) WHERE y <> blocked)+ (b)
