MATCH (head:ProcessInstrumentationFunction:PlantItem {tag: 'LSHH-44002'})-[:send_signal_to*0..]->(actuator:ActuatingFunction:PlantItem)-[:control]->(valve:Valve:PlantItem)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (head:ProcessInstrumentationFunction {loop_tag: 'PI-21019'})
MATCH (equipment:Equipment)-[:measured_by]->(sensor:PlantItem)
WHERE EXISTS { (sensor)-[:send_signal_to*0..]->(head) }
RETURN DISTINCT equipment.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'EJ-4301B'}), (b:PlantItem {tag: 'EJ-4302A'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
