MATCH (source:PlantItem {tag: 'P-3901B'})
MATCH (source)-[:line_to*1..]->(v:Valve)
WHERE EXISTS {
  MATCH (v)-[:line_to*1..]->(e:Equipment)
  WHERE e <> source
}
RETURN DISTINCT v.tag AS tag
