MATCH (loop:ProcessInstrumentationFunction {loop_tag: 'LIC-27032'})-[:send_signal_to*1..]->(actuator:PlantItem {kind: 'actuator'})-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem {tag: 'P-1901B'}), (v:PlantItem:Valve)
WHERE EXISTS { (p)-[:line_to*1..]->(v) }
  AND NOT EXISTS {
    MATCH (p)-[:line_to*1..]->(w:PlantItem:Valve)
    WHERE w <> v
      AND EXISTS { (w)-[:line_to*1..]->(v) }
  }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'P-601A'}), (b:PlantItem {tag: 'H-1201'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x)-[:line_to]->(y) WHERE y.tag <> 'XV-7007')+ (b)
       } AS can_flow

MATCH (a:PlantItem {tag: 'R-3901'}), (b:PlantItem {tag: 'P-3901B'})
RETURN EXISTS {
  MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE x.tag <> 'V-3901' AND y.tag <> 'V-3901')+ (b)
} AS can_flow_without_V_3901

MATCH (p:PlantItem {tag: 'P-4902B'}), (e:PlantItem {tag: 'E-5001'}), (v:Valve)
WHERE EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(e) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'TK-1603'}), (b:PlantItem {tag: 'F-1701B'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (v:Valve)-[:line_to*1..]->(:PlantItem {tag: 'D-1301'})
RETURN DISTINCT v.tag AS tag
