MATCH (a:PlantItem {tag: 'TK-5101'}), (b:PlantItem {tag: 'E-5203'}), (v:PlantItem {tag: 'GTV-51012'})
RETURN EXISTS {
  MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE x <> v AND y <> v)+ (b)
} AS reachable_without_GTV_51012

MATCH (start:PlantItem {tag: 'D-1501'}), (finish:PlantItem {tag: 'EA-1501'}), (v:Valve)
WHERE EXISTS { (start)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(finish) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'D-6001'}), (b:PlantItem {tag: 'TK-6202'}), (v:PlantItem:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN count(DISTINCT v.tag) AS valve_count

MATCH (a:PlantItem {tag: 'H-2501'}), (b:PlantItem {tag: 'E-3102'})
RETURN EXISTS {
  MATCH (a) ((x)-[:line_to]->(y) WHERE x.tag <> 'T-2701' AND y.tag <> 'T-2701')+ (b)
} AS can_flow_without_T_2701;

MATCH (a:PlantItem {tag: 'P-4101A'}), (b:PlantItem {tag: 'EJ-4301A'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'P-2101A'}), (b:PlantItem {tag: 'E-2403'}), (excluded:PlantItem {tag: 'E-2401'})
WHERE EXISTS {
  MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE x <> excluded AND y <> excluded)+ (b)
}
RETURN a.tag AS source_tag, b.tag AS destination_tag

MATCH (a:PlantItem {tag: 'P-502A'}), (b:PlantItem {tag: 'P-1004'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

