RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS { (a)-[:line_to*1..]->(b) } AS reachable;

MATCH (a:PlantItem {tag: 'EA-5701'}), (b:PlantItem {tag: 'P-5701A'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH p = shortestPath((a)-[:line_to*1..]->(b))
         WHERE ALL(n IN nodes(p) WHERE n.tag IS NULL OR n.tag <> 'GTV-57007')
       } AS reachable_without_GTV_57007

MATCH (a:PlantItem {tag: 'T-2701'}), (b:PlantItem {tag: 'TK-3601'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag
