MATCH (source:PlantItem {tag: 'P-4902A'})-[:line_to*1..]->(downstream:PlantItem)
WHERE downstream.unit_id IS NOT NULL AND downstream.unit_id <> source.unit_id
RETURN count(DISTINCT downstream.unit_id) AS other_unit_count;

MATCH (a:PlantItem {tag: 'EA-3301'}), (b:PlantItem {tag: 'E-5203'})
RETURN EXISTS {
  MATCH (a)-[:line_to*1..]->(b)
  WHERE NONE (v IN [x IN [] | x] WHERE v.tag = 'CHV-43005')
} AS reachable

MATCH (s:PlantItem {tag: 'D-2701'}), (t:PlantItem {tag: 'P-4101A'}), (v:Valve)
WHERE EXISTS { (s)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(t) }
RETURN count(DISTINCT v.tag) AS valve_count

MATCH (:PlantItem {tag: 'GTV-24004'})-[:line_to]->(item:PlantItem)
RETURN DISTINCT item.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'V-801'})-[:line_to]->(item:PlantItem)
RETURN DISTINCT item.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'E-5202'}), (b:PlantItem {tag: 'GTV-55011'})
MATCH p = shortestPath((a)-[:line_to*]->(b))
RETURN [n IN nodes(p) | n.tag] AS tags;

MATCH (p:PlantItem {tag: 'P-401B'}), (v:Valve:PlantItem)-[:line_to*1..]->(p)
WHERE NOT EXISTS {
  MATCH (v)-[:line_to*1..]->(w:Valve:PlantItem)-[:line_to*1..]->(p)
}
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (target:PlantItem {tag: 'V-4001'})
MATCH (v:Valve)-[:line_to*1..]->(target)
WHERE v <> target
  AND NOT EXISTS {
    MATCH (v)-[:line_to*1..]->(nearer:Valve)-[:line_to*1..]->(target)
    WHERE nearer <> v
  }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (target:PlantItem {tag: 'V-4001'})
MATCH (v:Valve)
WHERE EXISTS { (v)-[:line_to*1..]->(target) }
  AND NOT EXISTS {
    MATCH (v)-[:line_to*1..]->(nearer:Valve)
    WHERE nearer <> v
      AND EXISTS { (nearer)-[:line_to*1..]->(target) }
  }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (e:PlantItem:AirEjector {unit_id: '10'})
RETURN e.tag AS tag
ORDER BY tag;
